do $$
declare
  lv uuid; un uuid; ls uuid; ex uuid; nxt int;
begin
  select id into lv from levels where slug = 'elementary';
  select coalesce(max(order_index),0) into nxt from units where level_id = lv;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  select id into lv from levels where slug = 'intermediate';
  select coalesce(max(order_index),0) into nxt from units where level_id = lv;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  select id into lv from levels where slug = 'upper-intermediate';
  select coalesce(max(order_index),0) into nxt from units where level_id = lv;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  select id into lv from levels where slug = 'advanced';
  select coalesce(max(order_index),0) into nxt from units where level_id = lv;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  nxt := nxt + 1;
  select id into lv from levels where slug = 'beginner';
  select coalesce(max(order_index),0) into nxt from units where level_id = lv;
  nxt := nxt + 1;
end $$;
